# SPDX-License-Identifier: GPL-3.0-only
"""Tester actions for the six hardware tables in MCC45TR/uke-linux's Fedora README."""

UPSTREAM = "https://github.com/MCC45TR/uke-linux/blob/e6725304b4e40001705f043952e5db099a440b39/README.md#hardware-support"

# Stable ID, diagnostic group, display label, and what to observe on the tablet.
FEATURES = (
    ("fedora-boot", "boot", "Fedora startup", "Cold boot into Fedora using the stock boot chain. Record time to login and any splash, blank screen, or cursor."),
    ("cpu", "boot", "CPU and power profiles", "Check core count and frequency policies. Select available desktop power profiles and observe the policies under normal load."),
    ("memory", "boot", "RAM", "Compare reported RAM with this tablet's SKU. Record any failures during a sustained memory test in a separate session."),
    ("ufs", "boot", "UFS storage and ext4", "Copy and read back a temporary file in your home directory and verify its checksum. Record filesystem, scaling and WriteBooster evidence."),
    ("ufs-mcq", "boot", "UFS queues and inline crypto", "Record queue and crypto evidence. Qualify concurrent I/O and inline encryption only with a dedicated disposable test setup."),
    ("memory-counters", "boot", "Memory and cache counters", "Compare relevant perf counters and devfreq readings idle versus under load. Record unavailable counters or uncertain units."),
    ("reboot", "boot", "Normal reboot and slot acknowledgement", "Restart normally. Confirm Fedora login returns and compare boot IDs and the slot acknowledgement journal using two captures."),
    ("shutdown", "boot", "Shutdown and splash", "Power off from Fedora. Record visible splash, time to power-off, and any stalled jobs in the previous boot journal after powering on."),
    ("bootloader", "boot", "Bootloader entry", "Use your usual manual reboot-to-bootloader procedure and record where it lands. Restore Fedora before taking a second capture."),
    ("recovery", "boot", "Recovery entry", "Use your usual manual reboot-to-recovery procedure and record where it lands. Use TWRP capture if recovery is available."),
    ("virtualization", "boot", "UEFI, EL2 and KVM", "Record EFI presence, hypervisor evidence and /dev/kvm. If testing the separate UEFI build, confirm a guest starts with hardware acceleration."),
    ("panel", "graphics", "Built-in panel", "Check native resolution and usable picture in the desktop display panel."),
    ("fixed-refresh", "graphics", "Fixed refresh modes", "Select each offered refresh rate. Record stable modes and rates missing from the reference set of 30, 48, 50, 60, 90, 120 and 144 Hz."),
    ("backlight", "graphics", "Manual backlight", "Move the slider through 0, 5, 10, 25, 50 and 100%. Capture requested and actual brightness at each step and note visible jumps."),
    ("display-blank", "graphics", "Display blanking and return", "Blank or lock the display without suspending. Wake it and verify the desktop is responsive."),
    ("color-depth", "graphics", "Panel color depth", "Record the active format and link details from compositor or DRM evidence, and whether the depth can be selected."),
    ("touch", "input", "Touch and multitouch", "Touch corners and use a two-finger gesture. Note coordinate errors, dropped contacts, and behavior after wake."),
    ("vrr", "graphics", "Variable refresh", "Enable adaptive sync and vary an app's frame rate. Record the observed refresh range using compositor or panel telemetry."),
    ("wayland", "graphics", "Plasma and Wayland", "Confirm the session type and use a few normal desktop apps. Record lag, stutter, or rendering problems."),
    ("opengl", "graphics", "Adreno OpenGL and GLES", "Check EGL and the compositor renderer. Run a GL app and record whether rendering uses the Adreno GPU."),
    ("vulkan-opencl", "graphics", "Vulkan and OpenCL", "Record detected GPU devices. Run a Vulkan transfer/image workload and an OpenCL compute workload if tools are available."),
    ("webgpu", "graphics", "Browser GL and WebGPU", "Use the browser's GPU diagnostics and run a WebGL and WebGPU sample with the default browser sandbox. Record the adapter and failures."),
    ("buttons", "input", "Power and volume keys", "Press the power and each volume key in Fedora. Record events or the desktop response and test wake separately."),
    ("stylus", "input", "Pen, pressure and tilt", "Draw strokes at different pressures and angles in a pen-aware app. Record which inputs respond."),
    ("usb-mouse", "input", "USB mouse", "Connect the mouse or its receiver directly or through a dock. Verify movement, clicks and scrolling."),
    ("keyboard", "input", "USB and pogo keyboards", "Type using each available keyboard and check the pogo touchpad where present."),
    ("onscreen-keyboard", "input", "On-screen keyboard", "Focus a text field using touch and enter text. On TTY, check the framebuffer keyboard at login."),
    ("wifi", "network", "Wi-Fi and SSH", "Verify normal reconnect after boot, SSH reachability and a file transfer. Capture again after a failure or roam."),
    ("bluetooth", "network", "Bluetooth accessories", "Pair a mouse and headset, reconnect both, and verify input and stereo playback. Record the codec and microphone mode if tested."),
    ("kde-connect", "network", "KDE Connect", "Discover a peer on the same network, pair it and transfer a small file if available."),
    ("type-c", "network", "USB-C roles and accessory power", "Attach and detach the host cable, charger and dock separately. Capture reported roles and confirm each accessory works again after reconnecting."),
    ("superspeed", "network", "USB SuperSpeed", "Attach a known USB 3 device, check negotiated speed, and measure ordinary file transfer on removable storage if available."),
    ("usb-gadgets", "network", "USB serial and network gadgets", "If configured on the test image, verify the PC can open the CDC serial port and reach the tablet over the USB network."),
    ("usb-hubs", "network", "USB hub ports", "Connect USB 2 and USB 3 peripherals through the dock. Verify enumeration and that both function."),
    ("external-video", "graphics", "USB-C monitor output", "Attach a monitor through USB-C or HDMI dock. Record stable resolutions, refresh rates and formats from desktop settings."),
    ("external-hdr", "graphics", "External HDR", "Enable HDR in the compositor on an HDR monitor. Check the monitor's input status and an HDR test clip."),
    ("displayport-mst", "graphics", "DisplayPort MST and lanes", "Use compatible DisplayPort gear. Record the negotiated link and verify 4K60 and independent MST outputs where available."),
    ("external-dsc", "graphics", "External DSC and FEC", "Use a supported monitor and mode, then confirm DSC and FEC through link diagnostics or the monitor rather than inferring them from resolution."),
    ("monitor-ddc", "graphics", "Monitor brightness control", "Try a DDC/CI brightness query and change with a compatible display, then restore the original setting. Record whether the monitor responds."),
    ("usb-ethernet", "network", "USB Ethernet", "Connect a supported adapter and confirm the negotiated link, network transfer and receive-drop counts."),
    ("nfc", "network", "POCO NFC tag interface", "On a suitable POCO variant, verify an external reader sees the configured tag. Record variant and exposed service or driver evidence."),
    ("infrared", "network", "Infrared output", "With an IR receiver and a known test signal, verify optical output or receiver response using the supported device controls."),
    ("rotation", "sensors", "Automatic rotation", "Enable rotation and turn the tablet through all four orientations. Check touch alignment in each."),
    ("auto-brightness", "sensors", "Ambient-light brightness", "Enable automatic brightness. Cover and uncover the front and rear sensors in turn and observe brightness changes."),
    ("proximity", "sensors", "Front proximity", "Move a hand near and away from the sensor. Confirm the near/far reading or desktop response changes."),
    ("motion-compass", "sensors", "Gyroscope and compass", "Rotate on each axis and compare motion readings. Check compass headings against a reference away from magnets."),
    ("cover", "sensors", "Magnetic cover", "Open and close the cover and confirm input events. Record whether the display blanks and wakes."),
    ("ambient-color", "sensors", "Ambient color temperature", "Compare readings under known warm and cool lighting and note calibration if available."),
    ("flicker", "sensors", "Ambient light flicker", "Observe raw channels under steady and known flickering light. Record channels and units where known."),
    ("sar", "sensors", "SAR / body proximity", "Record the exposed state and whether a supported sensor test exists. Mark blocked if the feature is disabled."),
    ("speakers", "audio", "Internal speakers", "Keep volume low and play the test tone on the internal output. Use a channel test to verify speakers individually if routing permits."),
    ("microphones", "audio", "Internal microphones", "Record a short clip in a local recorder, then verify playback and check each exposed input channel."),
    ("external-audio", "audio", "Bluetooth and monitor audio", "Select Bluetooth and HDMI or DisplayPort audio in turn. Play the test tone and record the output and channel behavior."),
    ("usb-audio", "audio", "USB audio", "Select the USB audio device and verify playback and recording separately."),
    ("cameras", "media", "Front and rear cameras", "If a capture tool and camera nodes are present, preview both cameras separately. Record enumeration and any capture error."),
    ("video-codec", "media", "Native video encode and decode", "Use a local sample and a hardware codec with a media tool. Confirm hardware was selected and verify the output."),
    ("browser-video", "media", "VA-API and browser video", "Check exposed VA-API profiles and browser media diagnostics during playback. Record codec, resolution, hardware decode and dropped frames."),
    ("battery", "power", "Battery and temperatures", "Compare KDE or UPower battery readings with sysfs while charging and unplugged. Record missing charge, power or temperature fields."),
    ("charging", "power", "Charging and USB Power Delivery", "Check a known charger and powered dock. Record negotiated voltage/current from an available USB-PD meter and charging state from the tablet."),
    ("charge-limits", "power", "Battery charge limits", "If charge limits are exposed, verify charging stops and resumes around the configured thresholds during ordinary use."),
    ("charging-protection", "power", "Charging protection", "Capture exposed thermal and fault state in normal operation. Leave cutoff, moisture and fault validation to a controlled bench test."),
    ("battery-bypass", "power", "Battery bypass", "Compare charge state and net battery current on external power. For a pass, use independent evidence of the power path."),
    ("offline-charge", "power", "Charging while powered off", "Shut down manually and connect a charger. Record whether the tablet stays off, shows a charging screen, or boots."),
    ("s2idle", "power", "Suspend-to-idle", "Save work before testing. Suspend and resume manually; check touch, screen, SSH and repeated wake behavior."),
    ("deep-sleep", "power", "Deep sleep and input wake", "Check exposed sleep modes. If deep sleep is available, record power button or USB input wake and post-resume behavior."),
    ("hibernate", "power", "Hibernation", "Check swap and lockdown first. If the setup supports hibernation, perform a separate controlled test and verify session restore."),
    ("cable-wake", "power", "USB cable wake", "Suspend manually, reconnect a USB cable, and verify whether resume occurs without another wake source."),
    ("thermal", "power", "Thermal throttling", "Observe thermal and cooling-device readings during a normal workload. Record whether CPU or GPU limits engage."),
    ("led", "power", "RGB notification LED", "Use available controls to test colors and notification behavior, then restore the previous setting."),
    ("flashlight", "power", "Flashlight", "Toggle the supported torch control and confirm the LED physically lights and turns off."),
    ("clock", "power", "RTC and network time", "Compare the clock after an offline cold boot and after network sync. Record the raw RTC value and NTP status."),
    ("platform", "sensors", "PMIC and processor firmware", "Compare remote processor states and logs after boot. Record WPSS, ADSP, CDSP and any PMIC or restart warnings."),
    ("coresight", "boot", "CoreSight", "Read the captured kernel command line and logs for trace setup. Leave CoreSight disabled on normal hardware bring-up images."),
)
